// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    function setUp() public { c = new MONEY_BOX(); }
    function testRegression_property() public {
        c.SetMinSum(1);
        address logAddr = address(new Log());
        c.SetLogFile(logAddr);
        c.Initialized();
        vm.deal(address(this), 1);
        vm.warp(1);
        c.Put(0);
        vm.warp(2);
        c.Collect(1);
        bool ok;
        try c.SetMinSum(2) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok, "SetMinSum should revert after Initialized, but it didn't");
    }
}

contract Log {
    struct Message {
        address Sender;
        string  Data;
        uint Val;
        uint  Time;
    }

    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}
